const primary=Color(0xFF00A889),dark=Color(0xFF10241F),bg=Color(0xFFF5FAF8),line=Color(0xFFDDEBE6);
int n(dynamic v)=>v is num?v.toInt():int.tryParse('$v')??0;
String uid()=>DateTime.now().microsecondsSinceEpoch.toString();
String today()=>DateTime.now().toIso8601String().substring(0,10);
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();runApp(const App());}

class Store extends ChangeNotifier{
 late SharedPreferences p;List<Map<String,dynamic>> shops=[];int active=0;
 bool get registered=>shops.isNotEmpty;Map<String,dynamic>get shop=>registered?shops[active]:{};
 List<Map<String,dynamic>> list(String k){final x=shop[k];if(x is! List)return [];return x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}
 List<Map<String,dynamic>>get items=>list('items');List<Map<String,dynamic>>get customers=>list('customers');List<Map<String,dynamic>>get issued=>list('issued');List<Map<String,dynamic>>get returns=>list('returns');
 Future<void>load()async{p=await SharedPreferences.getInstance();try{final x=jsonDecode(p.getString('shops')??'[]');if(x is List)shops=x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){ }active=p.getInt('active')??0;if(active>=shops.length)active=shops.isEmpty?0:shops.length-1;}
 Map<String,dynamic>newShop(String a,String b,String c,String d)=>{'id':uid(),'name':a,'owner':b,'phone':c,'address':d,'items':[],'customers':[],'issued':[],'returns':[]};
 Future<void>save()async{await p.setString('shops',jsonEncode(shops));await p.setInt('active',active);}
 Future<void>addShop(String a,String b,String c,String d)async{shops.add(newShop(a,b,c,d));active=shops.length-1;await save();notifyListeners();}
 Future<void>changed()async{await save();notifyListeners();}
 Future<void>select(int i)async{active=i;await save();notifyListeners();}
 Future<void>delete(int i)async{shops.removeAt(i);if(active>=shops.length)active=shops.isEmpty?0:shops.length-1;await save();notifyListeners();}
}

